+const { useState, useId, useRef } = React;
+
+function NotificationPreferenceField({ value, onChange, error, describedById, errorId }) {
+  const name = "notification-preference";
+  const baseId = useId();
+
+  const options = [
+    { value: "email", label: "Email" },
+    { value: "sms", label: "SMS" },
+    { value: "push", label: "Push Notifications" },
+  ];
+
+  return (
+    <div className="form-field-wrapper">
+      <fieldset
+        className="form-field"
+        aria-describedby={`${describedById}${error ? " " + errorId : ""}`}
+      >
+        <legend>
+          How do you prefer to receive notifications?
+          <span className="required-marker" aria-hidden="true">*</span>
+        </legend>
+        <p id={describedById} className="help-text">
+          Choose one. Required fields are marked with an asterisk.
+        </p>
+        <div className="options" role="presentation">
+          {options.map((opt) => {
+            const id = `${baseId}-${opt.value}`;
+            return (
+              <label key={opt.value} className="option" htmlFor={id}>
+                <input
+                  id={id}
+                  type="radio"
+                  name={name}
+                  value={opt.value}
+                  checked={value === opt.value}
+                  onChange={(e) => onChange(e.target.value)}
+                  required
+                  aria-invalid={error ? "true" : undefined}
+                />
+                <span className="option-label">{opt.label}</span>
+              </label>
+            );
+          })}
+        </div>
+      </fieldset>
+    </div>
+  );
+}
+
+function NotificationForm() {
+  const [value, setValue] = useState("");
+  const [error, setError] = useState("");
+  const [status, setStatus] = useState({ tone: "", message: "" });
+  const fieldsetRef = useRef(null);
+
+  const helpId = "notif-help";
+  const errorId = "notif-error";
+
+  const handleSubmit = (e) => {
+    e.preventDefault();
+    if (!value) {
+      setError("Error: Please select how you'd like to receive notifications.");
+      setStatus({ tone: "error", message: "Please fix the highlighted field." });
+      const firstRadio = e.currentTarget.querySelector('input[type="radio"]');
+      if (firstRadio) firstRadio.focus();
+      return;
+    }
+    setError("");
+    const labelMap = { email: "Email", sms: "SMS", push: "Push Notifications" };
+    setStatus({ tone: "success", message: `Preference saved: ${labelMap[value]}.` });
+  };
+
+  const handleChange = (v) => {
+    setValue(v);
+    if (error) setError("");
+  };
+
+  return (
+    <form className="card" noValidate onSubmit={handleSubmit} aria-labelledby="form-title">
+      <NotificationPreferenceField
+        value={value}
+        onChange={handleChange}
+        error={error}
+        describedById={helpId}
+        errorId={errorId}
+      />
+      {error && (
+        <p id={errorId} className="status" data-tone="error" role="alert">
+          {error}
+        </p>
+      )}
+      <div className="actions">
+        <button type="submit" className="btn btn-primary">Save preference</button>
