const { chromium } = require('playwright');
const path = require('path');
const http = require('http');
const fs = require('fs');

const dir = __dirname;
const server = http.createServer((req, res) => {
  let p = req.url.split('?')[0];
  if (p === '/') p = '/index.html';
  const file = path.join(dir, p);
  if (!file.startsWith(dir) || !fs.existsSync(file)) { res.writeHead(404); res.end(); return; }
  const ext = path.extname(file);
  const types = { '.html': 'text/html', '.css': 'text/css', '.js': 'application/javascript' };
  res.writeHead(200, { 'Content-Type': types[ext] || 'text/plain' });
  res.end(fs.readFileSync(file));
});

(async () => {
  await new Promise(r => server.listen(0, r));
  const port = server.address().port;
  const browser = await chromium.launch();
  const page = await browser.newPage();
  page.on('pageerror', e => console.error('PAGEERROR:', e.message));
  await page.goto(`http://localhost:${port}/index.html`, { waitUntil: 'networkidle' });
  await page.waitForSelector('fieldset.form-field', { timeout: 10000 });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const r = await page.evaluate(async () => await window.axe.run());
  await browser.close();
  server.close();
  const wcag = r.violations.filter(v => !v.tags.includes('best-practice'));
  const bp   = r.violations.filter(v => v.tags.includes('best-practice'));
  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, help: v.help, targets: v.nodes.map(n => n.target), failureSummary: v.nodes.map(n => n.failureSummary) })),
    bp:   bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
  }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})();

